function_pipeline.input:
v=parent; e=envparent; export e; set -- 'one two' ''; readonly ro=fixed
g() { printf 'original_function\n'; }
f() { v=child; e=child; export e; cd /tmp; set -- changed; g() { printf 'child_function\n'; }; printf '%s:%s:%s:%s:%s\n' "$v" "$e" "$1" "$ro" "$PWD"; }
f | "$PROBE" copy
printf 'parent=%s:%s:%s:%s:%s:%s\n' "$v" "$e" "$1" "$#" "$ro" "$PWD"
g

builtin_pipeline.input:
PROBE=/out/probe; export PROBE
cd /
{
printf 'builtin words\n' | "$PROBE" copy
printf 'last=%s\n' "$?"
} > /out/builtin_pipeline.stdout

function_pipeline.input:
PROBE=/out/probe; export PROBE
cd /
{
v=parent; e=envparent; export e; set -- 'one two' ''; readonly ro=fixed
g() { printf 'original_function\n'; }
f() { v=child; e=child; export e; cd /tmp; set -- changed; g() { printf 'child_function\n'; }; printf '%s:%s:%s:%s:%s\n' "$v" "$e" "$1" "$ro" "$PWD"; }
f | "$PROBE" copy
printf 'parent=%s:%s:%s:%s:%s:%s\n' "$v" "$e" "$1" "$#" "$ro" "$PWD"
g
} > /out/function_pipeline.stdout

subshell_state.input:
PROBE=/out/probe; export PROBE
cd /
{
v=parent; export C2_EXPORTED=before; set -- 'alpha beta' ''; readonly fixed=immutable
g() { printf 'parent_function\n'; }
(v=child; C2_EXPORTED=after; export C2_EXPORTED; cd /tmp; set -- child; g() { printf 'child_function\n'; }; printf 'child=%s:%s:%s:%s:%s\n' "$v" "$C2_EXPORTED" "$1" "$fixed" "$PWD"; g)
printf 'parent=%s:%s:%s:%s:%s:%s\n' "$v" "$C2_EXPORTED" "$1" "$#" "$fixed" "$PWD"
g
} > /out/subshell_state.stdout

local_variable.input:
PROBE=/out/probe; export PROBE
cd /
{
f() { local v=inside; (v=child; printf 'child=%s\n' "$v"); printf 'local=%s\n' "$v"; }; v=outside; f; printf 'global=%s\n' "$v"
} > /out/local_variable.stdout

arithmetic_stage_isolation.input:
PROBE=/out/probe; export PROBE
cd /
{
x=5; "$PROBE" echo "$((x=x+1))" | "$PROBE" copy; printf 'parent_x=%s\n' "$x"
false; printf 'before=%s\n' "$?" | "$PROBE" copy; printf 'after=%s\n' "$?"
} > /out/arithmetic_stage_isolation.stdout

substitution_exit_status.input:
PROBE=/out/probe; export PROBE
cd /
{
a=$(printf 'value\n'; exit 23); s=$?; printf 'capture=<%s> status=%s\n' "$a" "$s"
b=$(false); s=$?; printf 'empty=<%s> status=%s\n' "$b" "$s"
} > /out/substitution_exit_status.stdout

substitution_large.input:
PROBE=/out/probe; export PROBE
cd /
{
value=$("$PROBE" text 32781); printf 'length=%s\n' "${#value}"; printf '%s' "$value" | "$PROBE" check 32781
} > /out/substitution_large.stdout

substitution_three_levels.input:
PROBE=/out/probe; export PROBE
cd /
{
a=$(b=$(c=$(printf nested); printf '%s' "$c"); printf '%s' "$b"); printf 'nested=<%s>\n' "$a"
} > /out/substitution_three_levels.stdout

function_pipeline_status.input:
PROBE=/out/probe; export PROBE
cd /
{
f() { printf data; return 17; }; g() { "$PROBE" copy; return 29; }; f | g; s=$?; printf '\nlast_status=%s\n' "$s"; test "$s" -eq 29
} > /out/function_pipeline_status.stdout

errexit_tested_pipeline_functions.input:
PROBE=/out/probe; export PROBE
cd /
{
set -e
f() { false; printf 'tested_function_continued\n'; }
if f | "$PROBE" copy; then printf 'if_pipeline_ok\n'; else printf 'BAD_IF_BRANCH\n'; fi
f | "$PROBE" copy && printf 'and_pipeline_ok\n'
printf 'set_e_parent_continued\n'
} > /out/errexit_tested_pipeline_functions.stdout

descriptor_restore.input:
PROBE=/out/probe; export PROBE
cd /
{
f() { printf 'child_file\n' > /out/child_marker; }; f | "$PROBE" copy; printf 'parent_stdout_restored\n'
(printf 'subshell_file\n' > /out/sub_marker); printf 'parent_again\n'
} > /out/descriptor_restore.stdout

depth_limit.input:
PROBE=/out/probe; export PROBE
cd /
{
a=$(b=$(c=$(d=$(printf UNREACHABLE_DEPTH)))); s=$?; if test "$s" -eq 0; then printf C2_DEPTH_BAD; exit 90; fi; printf 'C2_DEPTH_RECOVERED status=%s\n' "$s"
} > /out/depth_limit.stdout

fault_substitution.input:
PROBE=/out/probe; export PROBE
cd /
{
a=$("$PROBE" fault); s=$?; printf 'fault_capture=<%s> status=%s\n' "$a" "$s"; test "$s" -eq 137
} > /out/fault_substitution.stdout

fork_exhaustion.input:
PROBE=/out/probe; export PROBE
cd /
{
f() { while :; do :; done; }; f | f | f | f
} > /out/fork_exhaustion.stdout
